package com.bankcofferscanner;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("bankcofferscanner")
public interface BankCofferScannerConfig extends Config
{
    @ConfigItem(
        keyName = "onlyCofferEligible",
        name = "Coffer-eligible only",
        description = "Only list items worth at least 10,000gp, the minimum Death's Coffer sacrifice value",
        position = 1
    )
    default boolean onlyCofferEligible()
    {
        return true;
    }

    @ConfigItem(
        keyName = "minGeValue",
        name = "Minimum GE value",
        description = "Hide bank items whose Grand Exchange price is below this amount",
        position = 2
    )
    default int minGeValue()
    {
        return 0;
    }

    @ConfigItem(
        keyName = "minFlagRatio",
        name = "Warn: coffer/alch ratio",
        description = "Highlight items whose coffer value is at least this many times their High Alch value (e.g. 3 = coffer worth 3x+ alch). Set to 0 to turn off this check.",
        position = 3
    )
    default double minFlagRatio()
    {
        return 3.0;
    }

    @ConfigItem(
        keyName = "minFlagGpGap",
        name = "Warn: minimum gp gap",
        description = "Highlight items whose coffer value beats their High Alch value by at least this many gp. Set to 0 to turn off this check.",
        position = 4
    )
    default int minFlagGpGap()
    {
        return 100_000;
    }
}

package com.bankcofferscanner;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Insets;
import java.text.NumberFormat;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.Date;
import java.util.List;
import java.util.Locale;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JSpinner;
import javax.swing.SpinnerNumberModel;
import javax.swing.SwingConstants;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

/**
 * Side panel listing scanned bank items as a scrollable stack of cards (not a
 * wide table - a narrow sidebar can't show eight columns without horizontal
 * scrolling, which buried the numbers that actually matter). Each card shows
 * GE price, High Alch value, Death's Coffer sacrifice value (105% GE), the
 * per-item and stack-total profit of coffering over alching, and - for
 * stacked items - the total value of the whole stack alongside the per-item
 * price.
 * <p>
 * A "Show" mode controls how aggressively the list is filtered: only the
 * "big win" items that clear the configured warning thresholds (the same
 * ones used for the ⚠ highlight), any item where coffering edges out
 * alching by any amount, or everything. Optional toggles hide whole
 * categories (ores, cut gems, herblore supplies) and a minimum
 * quantity/total-value filter cuts out low-value clutter. Every filter and
 * sort choice persists across logins; only the per-row "Hide" button
 * permanently excludes a specific item.
 */
class BankCofferScannerPanel extends PluginPanel
{
    private static final NumberFormat GP_FORMAT = NumberFormat.getIntegerInstance(Locale.ENGLISH);
    private static final Color WARNING_COLOR = new Color(255, 180, 60);
    private static final Color POSITIVE_COLOR = new Color(80, 200, 120);
    private static final Color NEGATIVE_COLOR = new Color(220, 90, 90);
    private static final Color FLAGGED_BG = new Color(60, 45, 20);
    private static final Color ROW_BG = ColorScheme.DARKER_GRAY_COLOR;

    private static final String[] SHOW_MODE_LABELS = {"Recommended (big wins)", "Any coffer edge", "All items"};
    private static final String[] SHOW_MODE_KEYS = {"recommended", "any_edge", "all"};

    private static final String[] SORT_MODE_LABELS = {"Stack profit (total)", "Profit per item", "Coffer value"};
    private static final String[] SORT_MODE_KEYS = {"stack_profit", "per_item", "coffer_value"};

    private final BankCofferScannerPlugin plugin;
    private final BankCofferScannerConfig config;

    private final JLabel statusLabel = new JLabel("Open your bank, then click Scan Bank.");
    private final JCheckBox eligibleOnlyCheckbox = new JCheckBox("Coffer-eligible only (≥ 10,000 gp)");
    private final JComboBox<String> showModeCombo = new JComboBox<>(SHOW_MODE_LABELS);
    private final JComboBox<String> sortModeCombo = new JComboBox<>(SORT_MODE_LABELS);
    private final JCheckBox hideOresCheckbox = new JCheckBox("Hide ores");
    private final JCheckBox hideGemsCheckbox = new JCheckBox("Hide cut gems");
    private final JCheckBox hideHerbloreCheckbox = new JCheckBox("Hide herblore supplies");
    private final JCheckBox hideTeleportsCheckbox = new JCheckBox("Hide teleports");
    private final JSpinner minQtySpinner = new JSpinner(new SpinnerNumberModel(1, 1, 1_000_000, 1));
    private final JSpinner minTotalValueSpinner = new JSpinner(new SpinnerNumberModel(0L, 0L, Long.MAX_VALUE, 10_000L));
    private final JLabel hiddenLabel = new JLabel(" ");
    private final JButton resetHiddenButton = new JButton("Reset");
    private final JLabel summaryLabel = new JLabel(" ");
    private final JPanel resultsContainer = new JPanel();

    private List<BankItemValue> allResults = new ArrayList<>();

    BankCofferScannerPanel(BankCofferScannerPlugin plugin, BankCofferScannerConfig config)
    {
        super(false);
        this.plugin = plugin;
        this.config = config;

        setLayout(new BorderLayout(0, 8));
        setBorder(new EmptyBorder(10, 10, 10, 10));

        resultsContainer.setLayout(new BoxLayout(resultsContainer, BoxLayout.Y_AXIS));
        resultsContainer.setOpaque(false);

        JScrollPane scrollPane = new JScrollPane(resultsContainer);
        scrollPane.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH, 400));
        scrollPane.getVerticalScrollBar().setUnitIncrement(12);

        add(buildTopPanel(), BorderLayout.NORTH);
        add(scrollPane, BorderLayout.CENTER);

        updateHiddenLabel();
    }

    private JPanel buildTopPanel()
    {
        JPanel topPanel = new JPanel();
        topPanel.setLayout(new BoxLayout(topPanel, BoxLayout.Y_AXIS));
        topPanel.setOpaque(false);

        JLabel title = new JLabel("Coffer sac (105% GE) vs High Alch");
        title.setForeground(Color.WHITE);
        title.setAlignmentX(Component.LEFT_ALIGNMENT);

        JButton scanButton = new JButton("Scan Bank");
        scanButton.setAlignmentX(Component.LEFT_ALIGNMENT);
        scanButton.addActionListener(e -> plugin.requestScan());

        // --- Coffer-eligible only ---
        eligibleOnlyCheckbox.setSelected(config.onlyCofferEligible());
        eligibleOnlyCheckbox.setOpaque(false);
        eligibleOnlyCheckbox.setForeground(Color.LIGHT_GRAY);
        eligibleOnlyCheckbox.setAlignmentX(Component.LEFT_ALIGNMENT);
        eligibleOnlyCheckbox.addActionListener(e ->
        {
            plugin.setFilterSetting(BankCofferScannerPlugin.KEY_ELIGIBLE_ONLY, String.valueOf(eligibleOnlyCheckbox.isSelected()));
            applyFilter();
        });

        // --- Show mode ---
        showModeCombo.setSelectedIndex(indexOf(SHOW_MODE_KEYS,
            plugin.getFilterSetting(BankCofferScannerPlugin.KEY_SHOW_MODE, SHOW_MODE_KEYS[0]), 0));
        showModeCombo.setAlignmentX(Component.LEFT_ALIGNMENT);
        showModeCombo.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
        showModeCombo.setToolTipText("Recommended = only items whose coffer edge clears the Warn thresholds in this plugin's "
            + "settings. Any coffer edge = coffer beats HA by any amount, even a few gp. All items = no coffer-vs-HA filtering.");
        showModeCombo.addActionListener(e ->
        {
            plugin.setFilterSetting(BankCofferScannerPlugin.KEY_SHOW_MODE, SHOW_MODE_KEYS[showModeCombo.getSelectedIndex()]);
            applyFilter();
        });

        // --- Category toggles ---
        hideOresCheckbox.setSelected(Boolean.parseBoolean(plugin.getFilterSetting(BankCofferScannerPlugin.KEY_HIDE_ORES, "false")));
        hideGemsCheckbox.setSelected(Boolean.parseBoolean(plugin.getFilterSetting(BankCofferScannerPlugin.KEY_HIDE_GEMS, "false")));
        hideHerbloreCheckbox.setSelected(Boolean.parseBoolean(plugin.getFilterSetting(BankCofferScannerPlugin.KEY_HIDE_HERBLORE, "false")));
        hideTeleportsCheckbox.setSelected(Boolean.parseBoolean(plugin.getFilterSetting(BankCofferScannerPlugin.KEY_HIDE_TELEPORTS, "false")));
        for (JCheckBox categoryBox : new JCheckBox[] {hideOresCheckbox, hideGemsCheckbox, hideHerbloreCheckbox, hideTeleportsCheckbox})
        {
            categoryBox.setOpaque(false);
            categoryBox.setForeground(Color.LIGHT_GRAY);
            categoryBox.setAlignmentX(Component.LEFT_ALIGNMENT);
        }
        hideOresCheckbox.addActionListener(e ->
        {
            plugin.setFilterSetting(BankCofferScannerPlugin.KEY_HIDE_ORES, String.valueOf(hideOresCheckbox.isSelected()));
            applyFilter();
        });
        hideGemsCheckbox.addActionListener(e ->
        {
            plugin.setFilterSetting(BankCofferScannerPlugin.KEY_HIDE_GEMS, String.valueOf(hideGemsCheckbox.isSelected()));
            applyFilter();
        });
        hideHerbloreCheckbox.addActionListener(e ->
        {
            plugin.setFilterSetting(BankCofferScannerPlugin.KEY_HIDE_HERBLORE, String.valueOf(hideHerbloreCheckbox.isSelected()));
            applyFilter();
        });
        hideTeleportsCheckbox.addActionListener(e ->
        {
            plugin.setFilterSetting(BankCofferScannerPlugin.KEY_HIDE_TELEPORTS, String.valueOf(hideTeleportsCheckbox.isSelected()));
            applyFilter();
        });

        // --- Min qty / min total value (set before wiring listeners, so loading the
        // persisted value on startup doesn't itself trigger a spurious re-filter/save) ---
        minQtySpinner.setValue(parseIntSafe(plugin.getFilterSetting(BankCofferScannerPlugin.KEY_MIN_QTY, "1"), 1));
        minTotalValueSpinner.setValue(parseLongSafe(plugin.getFilterSetting(BankCofferScannerPlugin.KEY_MIN_TOTAL_VALUE, "0"), 0L));
        JPanel qtyRow = buildSpinnerRow("Min qty:", minQtySpinner, BankCofferScannerPlugin.KEY_MIN_QTY);
        JPanel valueRow = buildSpinnerRow("Min total value (gp):", minTotalValueSpinner, BankCofferScannerPlugin.KEY_MIN_TOTAL_VALUE);

        // --- Sort mode ---
        sortModeCombo.setSelectedIndex(indexOf(SORT_MODE_KEYS,
            plugin.getFilterSetting(BankCofferScannerPlugin.KEY_SORT_MODE, SORT_MODE_KEYS[0]), 0));
        sortModeCombo.setAlignmentX(Component.LEFT_ALIGNMENT);
        sortModeCombo.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
        sortModeCombo.addActionListener(e ->
        {
            plugin.setFilterSetting(BankCofferScannerPlugin.KEY_SORT_MODE, SORT_MODE_KEYS[sortModeCombo.getSelectedIndex()]);
            applyFilter();
        });

        statusLabel.setForeground(Color.LIGHT_GRAY);
        statusLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        statusLabel.setHorizontalAlignment(SwingConstants.LEFT);

        summaryLabel.setForeground(Color.WHITE);
        summaryLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        summaryLabel.setFont(summaryLabel.getFont().deriveFont(Font.BOLD, 11f));

        JPanel hiddenRow = new JPanel();
        hiddenRow.setLayout(new BoxLayout(hiddenRow, BoxLayout.X_AXIS));
        hiddenRow.setOpaque(false);
        hiddenRow.setAlignmentX(Component.LEFT_ALIGNMENT);
        hiddenLabel.setForeground(Color.LIGHT_GRAY);
        resetHiddenButton.setFont(resetHiddenButton.getFont().deriveFont(10f));
        resetHiddenButton.setMargin(new Insets(1, 6, 1, 6));
        resetHiddenButton.addActionListener(e ->
        {
            plugin.clearExclusions();
            plugin.requestScan();
        });
        hiddenRow.add(hiddenLabel);
        hiddenRow.add(Box.createHorizontalStrut(6));
        hiddenRow.add(resetHiddenButton);

        topPanel.add(title);
        topPanel.add(Box.createVerticalStrut(8));
        topPanel.add(scanButton);
        topPanel.add(Box.createVerticalStrut(8));
        topPanel.add(eligibleOnlyCheckbox);
        topPanel.add(Box.createVerticalStrut(6));
        topPanel.add(smallLabel("Show:"));
        topPanel.add(showModeCombo);
        topPanel.add(Box.createVerticalStrut(6));
        topPanel.add(hideOresCheckbox);
        topPanel.add(hideGemsCheckbox);
        topPanel.add(hideHerbloreCheckbox);
        topPanel.add(hideTeleportsCheckbox);
        topPanel.add(Box.createVerticalStrut(6));
        topPanel.add(qtyRow);
        topPanel.add(Box.createVerticalStrut(4));
        topPanel.add(valueRow);
        topPanel.add(Box.createVerticalStrut(6));
        topPanel.add(smallLabel("Sort by:"));
        topPanel.add(sortModeCombo);
        topPanel.add(Box.createVerticalStrut(6));
        topPanel.add(hiddenRow);
        topPanel.add(Box.createVerticalStrut(6));
        topPanel.add(statusLabel);
        topPanel.add(Box.createVerticalStrut(2));
        topPanel.add(summaryLabel);

        return topPanel;
    }

    private JLabel smallLabel(String text)
    {
        JLabel label = new JLabel(text);
        label.setForeground(Color.LIGHT_GRAY);
        label.setAlignmentX(Component.LEFT_ALIGNMENT);
        label.setFont(label.getFont().deriveFont(10f));
        return label;
    }

    /**
     * Builds a "label + spinner" row and wires the spinner so that both
     * clicking its arrows and typing a value then pressing Enter persist the
     * new value (under {@code settingKey}) and re-apply the filter.
     */
    private JPanel buildSpinnerRow(String labelText, JSpinner spinner, String settingKey)
    {
        JPanel row = new JPanel();
        row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
        row.setOpaque(false);
        row.setAlignmentX(Component.LEFT_ALIGNMENT);

        JLabel label = new JLabel(labelText);
        label.setForeground(Color.LIGHT_GRAY);
        label.setFont(label.getFont().deriveFont(10f));

        spinner.setMaximumSize(new Dimension(95, 22));
        spinner.setPreferredSize(new Dimension(95, 22));

        Runnable onChange = () ->
        {
            plugin.setFilterSetting(settingKey, String.valueOf(spinner.getValue()));
            applyFilter();
        };
        spinner.addChangeListener(e -> onChange.run());
        ((JSpinner.DefaultEditor) spinner.getEditor()).getTextField().addActionListener(e -> onChange.run());

        row.add(label);
        row.add(Box.createHorizontalStrut(6));
        row.add(spinner);
        return row;
    }

    void updateResults(List<BankItemValue> results)
    {
        this.allResults = results;
        applyFilter();
        statusLabel.setText(results.size() + " item" + (results.size() == 1 ? "" : "s") + " scanned"
            + " — " + new SimpleDateFormat("HH:mm", Locale.ENGLISH).format(new Date()));
        updateHiddenLabel();
    }

    void showBankNotOpenNotice()
    {
        statusLabel.setText("Open your bank first, then click Scan Bank.");
    }

    void showStaleNotice()
    {
        statusLabel.setText("Logged out - results may be stale.");
    }

    private void updateHiddenLabel()
    {
        int count = plugin.getExcludedItemIds().size();
        hiddenLabel.setText(count == 0 ? " " : count + " item" + (count == 1 ? "" : "s") + " hidden");
        resetHiddenButton.setVisible(count > 0);
    }

    /**
     * Called from the per-row "Hide" button. Persists the exclusion and
     * removes the row from view immediately, without waiting on a full
     * re-scan round trip.
     */
    private void hideItem(BankItemValue value)
    {
        plugin.excludeItem(value.getItemId());
        allResults.remove(value);
        applyFilter();
        updateHiddenLabel();
    }

    private void applyFilter()
    {
        boolean eligibleOnly = eligibleOnlyCheckbox.isSelected();
        String showMode = SHOW_MODE_KEYS[showModeCombo.getSelectedIndex()];
        boolean hideOres = hideOresCheckbox.isSelected();
        boolean hideGems = hideGemsCheckbox.isSelected();
        boolean hideHerblore = hideHerbloreCheckbox.isSelected();
        boolean hideTeleports = hideTeleportsCheckbox.isSelected();
        int minGeValue = Math.max(0, config.minGeValue());
        int minQty = (Integer) minQtySpinner.getValue();
        long minTotalValue = (Long) minTotalValueSpinner.getValue();

        List<BankItemValue> filtered = new ArrayList<>();
        for (BankItemValue value : allResults)
        {
            if (eligibleOnly && !value.isCofferEligible())
            {
                continue;
            }
            if (hideOres && ItemCategory.isOre(value.getName()))
            {
                continue;
            }
            if (hideGems && ItemCategory.isCutGem(value.getName()))
            {
                continue;
            }
            if (hideHerblore && ItemCategory.isHerbloreSupply(value.getName()))
            {
                continue;
            }
            if (hideTeleports && ItemCategory.isTeleport(value.getName()))
            {
                continue;
            }
            if (value.getGePrice() < minGeValue)
            {
                continue;
            }
            if (value.getQuantity() < minQty)
            {
                continue;
            }
            long totalValue = (long) value.getGePrice() * value.getQuantity();
            if (totalValue < minTotalValue)
            {
                continue;
            }
            if ("recommended".equals(showMode) && !isFlagged(value))
            {
                continue;
            }
            if ("any_edge".equals(showMode) && value.getCofferValue() <= value.getHaPrice())
            {
                continue;
            }
            filtered.add(value);
        }
        filtered.sort(sortComparator());

        renderRows(filtered);
        updateSummary(filtered);
    }

    private Comparator<BankItemValue> sortComparator()
    {
        String sortMode = SORT_MODE_KEYS[sortModeCombo.getSelectedIndex()];
        if ("per_item".equals(sortMode))
        {
            return Comparator.comparingLong(BankItemValue::getCofferAdvantagePerItem).reversed();
        }
        if ("coffer_value".equals(sortMode))
        {
            return Comparator.comparingLong(BankItemValue::getCofferValue).reversed();
        }
        return Comparator.comparingLong(BankItemValue::getCofferAdvantageTotal).reversed();
    }

    private void renderRows(List<BankItemValue> filtered)
    {
        resultsContainer.removeAll();
        for (BankItemValue value : filtered)
        {
            resultsContainer.add(buildRow(value));
            resultsContainer.add(Box.createVerticalStrut(1));
        }
        resultsContainer.revalidate();
        resultsContainer.repaint();
    }

    private void updateSummary(List<BankItemValue> filtered)
    {
        if (filtered.isEmpty())
        {
            summaryLabel.setText(allResults.isEmpty() ? " " : "No items match the current filters.");
            return;
        }

        long totalCoffer = 0;
        long totalProfit = 0;
        for (BankItemValue v : filtered)
        {
            totalCoffer += v.getCofferValue() * v.getQuantity();
            totalProfit += v.getCofferAdvantageTotal();
        }

        summaryLabel.setText("<html>" + filtered.size() + " item" + (filtered.size() == 1 ? "" : "s") + " found<br>"
            + "Total coffer value: " + GP_FORMAT.format(totalCoffer) + " gp<br>"
            + "Profit vs High Alch: " + (totalProfit >= 0 ? "+" : "") + GP_FORMAT.format(totalProfit) + " gp</html>");
    }

    /**
     * An item "greatly outweighs" its alch value when either the configured
     * ratio or flat gp gap threshold is met. Items that can't be High Alched
     * at all (haPrice == 0) are never flagged - there's no "don't alch this"
     * warning to give for something you can't alch in the first place. This
     * same check is what "Show: Recommended" filters down to.
     */
    private boolean isFlagged(BankItemValue v)
    {
        if (v.getHaPrice() <= 0)
        {
            return false;
        }
        double minRatio = config.minFlagRatio();
        long minGap = config.minFlagGpGap();
        boolean ratioFlag = minRatio > 0 && v.getCofferValue() >= v.getHaPrice() * minRatio;
        boolean gapFlag = minGap > 0 && v.getCofferAdvantagePerItem() >= minGap;
        return ratioFlag || gapFlag;
    }

    private JPanel buildRow(BankItemValue v)
    {
        boolean flagged = isFlagged(v);
        int qty = v.getQuantity();
        long advantagePerItem = v.getCofferAdvantagePerItem();
        long stackProfit = v.getCofferAdvantageTotal();

        JPanel row = new JPanel(new BorderLayout(4, 2));
        row.setBackground(flagged ? FLAGGED_BG : ROW_BG);
        row.setBorder(new CompoundBorder(
            new MatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR),
            new EmptyBorder(6, 6, 6, 6)));

        JLabel nameLabel = new JLabel((flagged ? "⚠ " : "") + v.getName() + (qty > 1 ? " ×" + qty : ""));
        nameLabel.setForeground(flagged ? WARNING_COLOR : Color.WHITE);
        nameLabel.setFont(nameLabel.getFont().deriveFont(Font.BOLD));
        if (flagged)
        {
            nameLabel.setToolTipText(String.format("Coffer value is %.1fx High Alch (%s vs %s gp)",
                v.getCofferToAlchRatio(), GP_FORMAT.format(v.getCofferValue()), GP_FORMAT.format(v.getHaPrice())));
        }

        JButton hideButton = new JButton("Hide");
        hideButton.setFont(hideButton.getFont().deriveFont(9f));
        hideButton.setMargin(new Insets(1, 4, 1, 4));
        hideButton.addActionListener(e -> hideItem(v));

        JPanel headerRow = new JPanel(new BorderLayout());
        headerRow.setOpaque(false);
        headerRow.add(nameLabel, BorderLayout.CENTER);
        headerRow.add(hideButton, BorderLayout.EAST);

        JPanel details = new JPanel();
        details.setLayout(new BoxLayout(details, BoxLayout.Y_AXIS));
        details.setOpaque(false);

        details.add(detailLine("GE: " + formatWithTotal(v.getGePrice(), qty), Color.LIGHT_GRAY));
        details.add(detailLine("HA: " + formatWithTotal(v.getHaPrice(), qty), Color.LIGHT_GRAY));
        details.add(detailLine("Coffer: " + formatWithTotal(v.getCofferValue(), qty), Color.LIGHT_GRAY));

        Color advColor = advantagePerItem >= 0 ? POSITIVE_COLOR : NEGATIVE_COLOR;
        details.add(detailLine((advantagePerItem >= 0 ? "+" : "") + GP_FORMAT.format(advantagePerItem) + " gp/item vs HA", advColor));

        if (qty > 1)
        {
            details.add(detailLine("Stack profit: " + (stackProfit >= 0 ? "+" : "") + GP_FORMAT.format(stackProfit) + " gp", advColor));
        }

        row.add(headerRow, BorderLayout.NORTH);
        row.add(details, BorderLayout.CENTER);
        return row;
    }

    /**
     * "216,213 gp" for a single item, or "24,936 gp  (×30 = 748,080 gp)" for
     * a stack, so both the per-item price and the full stack's value are
     * visible without any extra clicks.
     */
    private static String formatWithTotal(long perItem, int qty)
    {
        if (qty <= 1)
        {
            return GP_FORMAT.format(perItem) + " gp";
        }
        return GP_FORMAT.format(perItem) + " gp  (×" + qty + " = " + GP_FORMAT.format(perItem * (long) qty) + " gp)";
    }

    private JLabel detailLine(String text, Color color)
    {
        JLabel label = new JLabel(text);
        label.setForeground(color);
        label.setFont(label.getFont().deriveFont(11f));
        return label;
    }

    private static int indexOf(String[] values, String target, int fallback)
    {
        for (int i = 0; i < values.length; i++)
        {
            if (values[i].equals(target))
            {
                return i;
            }
        }
        return fallback;
    }

    private static int parseIntSafe(String s, int fallback)
    {
        try
        {
            return Integer.parseInt(s);
        }
        catch (NumberFormatException e)
        {
            return fallback;
        }
    }

    private static long parseLongSafe(String s, long fallback)
    {
        try
        {
            return Long.parseLong(s);
        }
        catch (NumberFormatException e)
        {
            return fallback;
        }
    }
}

package com.bankcofferscanner;

