/**
 * Scans the player's bank and, for every item, compares two ways of "cashing
 * it in":
 * <p>
 * - Sacrificing it to Death's Coffer, which pays 105% of the item's Grand
 * Exchange price (items worth 10,000gp+ only; see the OSRS Wiki page on
 * Death's Coffer).
 * - High Alchemy, which pays the item's fixed alchemy value.
 * <p>
 * The side panel lists every bank item sorted by how much better (or worse)
 * sacrificing beats alching, so you can see at a glance which items are
 * "coffer fodder" vs. which are better off run through High Alchemy.
 */
@Slf4j
@PluginDescriptor(
    name = "Bank Coffer vs Alch",
    description = "Compares Death's Coffer sacrifice value (105% GE price) against High Alchemy value for every item in your bank",
    tags = {"bank", "alch", "alchemy", "coffer", "death", "value", "grand exchange", "ge"}
)
public class BankCofferScannerPlugin extends Plugin
{
    /**
     * Death's Coffer only accepts items whose GE price is at least this much.
     * Source: OSRS Wiki, "Death's Coffer".
     */
    static final int COFFER_MIN_GE_VALUE = 10_000;

    /**
     * Death's Coffer pays out 105% of an item's Grand Exchange price.
     * Source: OSRS Wiki, "Death's Coffer".
     */
    static final double COFFER_MULTIPLIER = 1.05;

    /**
     * Config key (under this plugin's config group) holding a comma-separated
     * list of canonical item IDs the user has manually hidden via the "Hide"
     * button in the panel. Deliberately not a {@code @ConfigItem} - it's
     * managed entirely by button clicks, not meant to be hand-edited in the
     * plugin's config panel.
     */
    private static final String CONFIG_GROUP = "bankcofferscanner";
    private static final String EXCLUDED_ITEMS_KEY = "excludedItemIds";

    /**
     * Keys (under this plugin's config group) for the panel's filter/sort
     * controls. Like {@link #EXCLUDED_ITEMS_KEY}, these are read/written
     * straight through {@link ConfigManager} rather than being
     * {@code @ConfigItem}s, so the panel's own widgets are the only editor
     * for them - but storing them through ConfigManager means they persist
     * across logout/client-restart the same way any other setting does.
     */
    /** Matches {@code BankCofferScannerConfig#onlyCofferEligible()}'s {@code keyName} exactly. */
    static final String KEY_ELIGIBLE_ONLY = "onlyCofferEligible";
    static final String KEY_SHOW_MODE = "showMode";
    static final String KEY_SORT_MODE = "sortMode";
    static final String KEY_MIN_QTY = "filterMinQty";
    static final String KEY_MIN_TOTAL_VALUE = "filterMinTotalValue";
    static final String KEY_HIDE_ORES = "filterHideOres";
    static final String KEY_HIDE_GEMS = "filterHideGems";
    static final String KEY_HIDE_HERBLORE = "filterHideHerblore";
    static final String KEY_HIDE_TELEPORTS = "filterHideTeleports";

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ItemManager itemManager;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private BankCofferScannerConfig config;

    @Inject
    private ConfigManager configManager;

    private BankCofferScannerPanel panel;
    private NavigationButton navButton;

    @Provides
    BankCofferScannerConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(BankCofferScannerConfig.class);
    }

    @Override
    protected void startUp()
    {
        panel = new BankCofferScannerPanel(this, config);

        final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");

        navButton = NavigationButton.builder()
            .tooltip("Bank Coffer vs Alch")
            .icon(icon)
            .priority(6)
            .panel(panel)
            .build();

        clientToolbar.addNavigation(navButton);
    }

    @Override
    protected void shutDown()
    {
        clientToolbar.removeNavigation(navButton);
        panel = null;
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (event.getContainerId() == InventoryID.BANK)
        {
            scanBank(event.getItemContainer());
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        GameState state = event.getGameState();
        if (panel != null && (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.CONNECTION_LOST))
        {
            SwingUtilities.invokeLater(panel::showStaleNotice);
        }
    }

    /**
     * Invoked from the panel's "Scan Bank" button. Re-reads whatever bank
     * contents the client currently has cached (populated the last time the
     * bank interface was opened this session).
     */
    void requestScan()
    {
        clientThread.invoke(() ->
        {
            ItemContainer bank = client.getItemContainer(InventoryID.BANK);
            if (bank == null)
            {
                SwingUtilities.invokeLater(panel::showBankNotOpenNotice);
                return;
            }
            scanBank(bank);
        });
    }

    private void scanBank(ItemContainer bank)
    {
        if (bank == null || panel == null)
        {
            return;
        }

        Item[] items = bank.getItems();
        Set<Integer> excluded = getExcludedItemIds();
        List<BankItemValue> results = new ArrayList<>();

        for (Item item : items)
        {
            if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
            {
                continue;
            }

            int canonicalId = itemManager.canonicalize(item.getId());

            if (excluded.contains(canonicalId) || ItemCategory.isCurrency(canonicalId))
            {
                continue;
            }

            ItemComposition comp = itemManager.getItemComposition(canonicalId);

            int gePrice = itemManager.getItemPrice(canonicalId);
            int haPrice = comp.getHaPrice();

            if (gePrice <= 0 && haPrice <= 0)
            {
                // Neither tradeable nor alchable - nothing to compare.
                continue;
            }

            long cofferValue = Math.round(gePrice * COFFER_MULTIPLIER);
            boolean cofferEligible = gePrice >= COFFER_MIN_GE_VALUE;

            results.add(new BankItemValue(
                canonicalId,
                comp.getName(),
                item.getQuantity(),
                gePrice,
                haPrice,
                cofferValue,
                cofferEligible
            ));
        }

        SwingUtilities.invokeLater(() -> panel.updateResults(results));
    }

    /**
     * Item IDs the user has hidden via the panel's per-row "Hide" button.
     */
    Set<Integer> getExcludedItemIds()
    {
        String raw = configManager.getConfiguration(CONFIG_GROUP, EXCLUDED_ITEMS_KEY);
        Set<Integer> ids = new HashSet<>();
        if (raw != null && !raw.isEmpty())
        {
            for (String part : raw.split(","))
            {
                try
                {
                    ids.add(Integer.parseInt(part.trim()));
                }
                catch (NumberFormatException ignored)
                {
                    // Skip anything that doesn't parse rather than losing the whole list.
                }
            }
        }
        return ids;
    }

    /**
     * Persists one more item ID onto the hidden list. Does not by itself
     * refresh the panel - the panel removes the row immediately for instant
     * feedback, and future scans will simply skip this ID.
     */
    void excludeItem(int itemId)
    {
        Set<Integer> ids = getExcludedItemIds();
        ids.add(itemId);
        configManager.setConfiguration(CONFIG_GROUP, EXCLUDED_ITEMS_KEY,
            ids.stream().map(String::valueOf).collect(Collectors.joining(",")));
    }

    /**
     * Un-hides everything. Callers should follow this with {@link #requestScan()}
     * to bring the previously-hidden items back into view.
     */
    void clearExclusions()
    {
        configManager.unsetConfiguration(CONFIG_GROUP, EXCLUDED_ITEMS_KEY);
    }

    /**
     * Reads one of the panel's persisted filter/sort settings (see the
     * {@code KEY_*} constants above). Returns {@code defaultValue} the first
     * time it's read, before the user has touched that control.
     */
    String getFilterSetting(String key, String defaultValue)
    {
        String value = configManager.getConfiguration(CONFIG_GROUP, key);
        return value != null ? value : defaultValue;
    }

    /**
     * Persists one of the panel's filter/sort settings so it survives a
     * client restart.
     */
    void setFilterSetting(String key, String value)
    {
        configManager.setConfiguration(CONFIG_GROUP, key, value);
    }
}

package com.bankcofferscanner;

/**
 * A single bank item's value comparison between:
 * - what it would be worth if sacrificed to Death's Coffer (105% of its Grand
 *   Exchange price, per the OSRS Wiki), and
 * - what it would be worth if High Alched (the item's alchemy value).
 */
class BankItemValue
{
    private final int itemId;
    private final String name;
    private final int quantity;
    private final int gePrice;
    private final int haPrice;
    private final long cofferValue;
    private final boolean cofferEligible;

    BankItemValue(int itemId, String name, int quantity, int gePrice, int haPrice, long cofferValue, boolean cofferEligible)
    {
        this.itemId = itemId;
        this.name = name;
        this.quantity = quantity;
        this.gePrice = gePrice;
        this.haPrice = haPrice;
        this.cofferValue = cofferValue;
        this.cofferEligible = cofferEligible;
    }

    int getItemId()
    {
        return itemId;
    }

    String getName()
    {
        return name;
    }

    int getQuantity()
    {
        return quantity;
    }

    int getGePrice()
    {
        return gePrice;
    }

    int getHaPrice()
    {
        return haPrice;
    }

    /**
     * Per-item coffer sacrifice value (105% of GE price), regardless of whether
     * the item actually meets the coffer's 10,000gp eligibility floor.
     */
    long getCofferValue()
    {
        return cofferValue;
    }

    boolean isCofferEligible()
    {
        return cofferEligible;
    }

    /**
     * Positive => sacrificing one of this item to the coffer is worth more than
     * High Alching one. Negative => High Alching wins.
     */
    long getCofferAdvantagePerItem()
    {
        return cofferValue - haPrice;
    }

    /**
     * Same as {@link #getCofferAdvantagePerItem()} but multiplied out across the
     * full stack held in the bank.
     */
    long getCofferAdvantageTotal()
    {
        return getCofferAdvantagePerItem() * quantity;
    }

    /**
     * How many times over the coffer value beats the High Alch value (e.g. an
     * abyssal whip alching for 72k but sacrificing for ~800k is about 11.1).
     * Returns -1 when the item can't be High Alched at all (haPrice is 0), since
     * the ratio is meaningless in that case.
     */
    double getCofferToAlchRatio()
    {
        return haPrice > 0 ? (double) cofferValue / haPrice : -1;
    }
}

package com.bankcofferscanner;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;

/**
 * Best-effort item category matching used only by the panel's optional
 * "hide this category" filters (ores / cut gems / herblore supplies / teleports).
 * <p>
 * RuneLite has no official item-category API, so this is a curated,
 * hand-maintained list of names/patterns rather than anything derived from
 * the game's own data. It covers the standard, stable cases - the normal
 * ore types, the craftable/cuttable gems, and the core herblore herbs and
 * potions - but it can't be exhaustive: a brand new item added in a future
 * game update, an unusual herblore secondary ingredient that doesn't look
 * like a herb or a potion by name, etc. will simply not match and won't be
 * hidden by these toggles. The per-row "Hide" button remains the reliable
 * way to permanently exclude any specific item regardless of category.
 */
final class ItemCategory
{
    private static final Set<String> ORE_NAMES = new HashSet<>(Arrays.asList(
        "Copper ore", "Tin ore", "Iron ore", "Silver ore", "Coal", "Gold ore",
        "Mithril ore", "Adamantite ore", "Runite ore", "Amethyst", "Blurite ore",
        "Lovakite ore"
    ));

    private static final Set<String> CUT_GEM_NAMES = new HashSet<>(Arrays.asList(
        "Opal", "Jade", "Red topaz", "Sapphire", "Emerald", "Ruby", "Diamond",
        "Dragonstone", "Onyx", "Zenyte"
    ));

    private static final Set<String> HERB_NAMES = new HashSet<>(Arrays.asList(
        "Guam leaf", "Marrentill", "Tarromin", "Harralander", "Ranarr weed",
        "Toadflax", "Irit leaf", "Avantoe", "Kwuarm", "Snapdragon", "Cadantine",
        "Lantadyme", "Dwarf weed", "Torstol"
    ));

    /**
     * Coins and platinum tokens have no meaningful GE-vs-alch-vs-coffer
     * comparison to make - they ARE the currency being compared against.
     * Always excluded from scan results outright, not tied to any toggle.
     */
    private static final Set<Integer> CURRENCY_ITEM_IDS = new HashSet<>(Arrays.asList(995, 996));

    private ItemCategory()
    {
    }

    static boolean isTeleport(String name)
    {
        // Deliberately broad: catches every teleport tablet ("Varrock teleport",
        // "Kharyrll teleport", "Teleport to house", "Teleport to Kourend", ...) and
        // any item literally named with "teleport" in it (the common case for the
        // one-use "scroll"-style teleports players tend to mean by that word). Does
        // NOT match reusable teleport jewellery (rings, amulets, necklaces) since
        // those don't have "teleport" in their name and are gear you'd keep, not
        // bank clutter you'd sacrifice or alch.
        return name != null && name.toLowerCase(Locale.ENGLISH).contains("teleport");
    }

    static boolean isCurrency(int itemId)
    {
        return CURRENCY_ITEM_IDS.contains(itemId);
    }

    static boolean isOre(String name)
    {
        return name != null && ORE_NAMES.contains(name);
    }

    static boolean isCutGem(String name)
    {
        return name != null && CUT_GEM_NAMES.contains(name);
    }

    /**
     * Herbs (grimy or clean) plus unfinished and finished potions. Doesn't
     * attempt to catch every herblore secondary ingredient (eye of newt,
     * snape grass, etc.) - those don't follow a reliable name pattern and
     * are usually low-value enough that they're not what floods the list.
     */
    static boolean isHerbloreSupply(String name)
    {
        if (name == null)
        {
            return false;
        }
        if (HERB_NAMES.contains(name) || name.startsWith("Grimy "))
        {
            return true;
        }
        String lower = name.toLowerCase(Locale.ENGLISH);
        if (lower.endsWith("(unf)"))
        {
            return true;
        }
        // Finished potions, e.g. "Prayer potion(4)", "Super combat potion(1)"
        return lower.matches(".*potion\\([1-4]\\)$");
    }
}

